create or replace function public.fleet_create_driver(p_business_id uuid,p_name text,p_email text default null,p_phone text default null,p_status text default 'active',p_vehicle_id uuid default null,p_metadata jsonb default '{}'::jsonb) returns public.fleet_drivers language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare d public.fleet_drivers; begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; if nullif(trim(p_name),'') is null then raise exception 'Driver name required'; end if; if p_vehicle_id is not null and not exists(select 1 from public.fleet_vehicles where id=p_vehicle_id and business_id=p_business_id) then raise exception 'Vehicle not found'; end if; insert into public.fleet_drivers(business_id,name,email,phone,status,vehicle_id,metadata) values(p_business_id,trim(p_name),nullif(trim(p_email),''),nullif(trim(p_phone),''),coalesce(nullif(trim(p_status),''),'active'),p_vehicle_id,coalesce(p_metadata,'{}'::jsonb)) returning * into d; return d; end $$;

create or replace function public.fleet_create_vehicle(p_business_id uuid,p_name text,p_unit_code text default null,p_vehicle_type text default 'vehicle',p_status text default 'active',p_driver_name text default null,p_current_lat double precision default null,p_current_lng double precision default null,p_odometer_miles numeric default null,p_metadata jsonb default '{}'::jsonb) returns public.fleet_vehicles language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ declare v public.fleet_vehicles; begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; if nullif(trim(p_name),'') is null then raise exception 'Vehicle name required'; end if; insert into public.fleet_vehicles(business_id,name,unit_code,vehicle_type,status,driver_name,current_lat,current_lng,odometer_miles,metadata) values(p_business_id,trim(p_name),nullif(trim(p_unit_code),''),coalesce(nullif(trim(p_vehicle_type),''),'vehicle'),coalesce(nullif(trim(p_status),''),'active'),nullif(trim(p_driver_name),''),p_current_lat,p_current_lng,p_odometer_miles,coalesce(p_metadata,'{}'::jsonb)) returning * into v; return v; end $$;

create or replace function public.fleet_delete_driver(p_business_id uuid,p_driver_id uuid) returns boolean language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; delete from public.fleet_drivers where id=p_driver_id and business_id=p_business_id; return found; end $$;

create or replace function public.fleet_delete_vehicle(p_business_id uuid,p_vehicle_id uuid) returns boolean language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $$ begin if not public.fleet_actor_is_manager(p_business_id) then raise exception 'Fleet manager access required'; end if; delete from public.fleet_vehicles where id=p_vehicle_id and business_id=p_business_id; return found; end $$;
